'use strict';
const test=require('node:test');const assert=require('node:assert/strict');
let api;try{api=require('../lab-contracts.js');}catch(e){api={};}
const row=(overrides={})=>({logical_device:'temp_01_08',physical_device_id:'temperature_module_1',bus_id:'shared',serial_port:'TEST_ONLY',slave_id:1,baud_rate:19200,data_bits:8,parity:'none',stop_bits:1,function_code:3,register_start:1537,address_base:'matlab_address_1',register_count:8,channel_count:8,data_type:'int16',byte_order:'native16',scale:.1,offset:0,unit:'C',source:'modbus',verification_status:'verified',...overrides});
function ready(){assert.equal(typeof api.validateDeviceMap,'function','统一设备表验证尚未实现');}
test('同一物理设备多个信号可共享站号，不同设备同总线撞址被拒绝',()=>{ready();assert.deepEqual(api.validateDeviceMap([row(),row({logical_device:'temp_extra',register_start:1545})]),[]);assert.ok(api.validateDeviceMap([row(),row({logical_device:'valve',physical_device_id:'valve_1'})]).some(e=>e.code==='ADDRESS_COLLISION'));});
test('同一总线的帧参数和端口必须一致，未核实配置不能通过',()=>{ready();assert.ok(api.validateDeviceMap([row(),row({logical_device:'x',physical_device_id:'x',slave_id:5,baud_rate:9600})]).some(e=>e.code==='BUS_SETTINGS'));assert.ok(api.validateDeviceMap([row({verification_status:'unverified'})]).some(e=>e.code==='UNVERIFIED'));assert.ok(api.validateDeviceMap([row({register_start:''})]).some(e=>e.code==='MISSING'));});
test('不同总线复用地址可以单独检查，但本项目默认只允许一条总线',()=>{ready();const rows=[row(),row({logical_device:'x',physical_device_id:'x',bus_id:'other',serial_port:'TEST2'})];assert.ok(api.validateDeviceMap(rows).some(e=>e.code==='MULTIPLE_BUSES'));assert.deepEqual(api.validateDeviceMap(rows,{requireSingleBus:false}),[]);});
test('阀门请求、限幅、编码与反馈分别保留，不冒充已发送或实测',()=>{assert.equal(typeof api.makeValveCommand,'function');const c=api.makeValveCommand(90,{unit:'legacy_u_unverified',min:0,max:60,registerScale:100,registerOffset:0,verified:false});assert.equal(c.requested,90);assert.equal(c.clamped,60);assert.equal(c.registerValue,null);assert.equal(c.writeStatus,'NOT_SENT');assert.equal(c.actualFeedback,null);assert.throws(()=>api.makeValveCommand(90,{unit:'unknown',min:0,max:60},'real'),/核实|verified/);const verified=api.makeValveCommand(90,{unit:'test_u',min:0,max:60,registerScale:100,registerOffset:0,verified:true},'real');assert.equal(verified.registerValue,6000);assert.equal(verified.writeStatus,'NOT_SENT');});
test('阀门非数值及失效限幅参数直接拒绝',()=>{assert.equal(typeof api.makeValveCommand,'function');assert.throws(()=>api.makeValveCommand(NaN));assert.throws(()=>api.makeValveCommand(1,{unit:'percent',min:80,max:60}));});
test('反馈接口拒绝无效、超龄、未标定或原始探头，只接受窗口XYZ',()=>{assert.equal(typeof api.feedbackFromWindow,'function');const w={windowId:'W1',baselineId:'B1',kind:'thermal',valid:true,xyz:[1,-2,3],endWallSec:10,calibrationVersion:'demo-standard-v2'};assert.deepEqual(api.feedbackFromWindow(w,12,5).xyz,[1,-2,3]);for(const bad of [{...w,valid:false},{...w,xyz:[1,NaN,3]},{...w,baselineId:null},{...w,calibrationVersion:null},{...w,kind:'raw'}])assert.throws(()=>api.feedbackFromWindow(bad,12,5));assert.throws(()=>api.feedbackFromWindow(w,20,5));});
test('CSV支持BOM、引号与换行，不将空字段转成零',()=>{assert.equal(typeof api.parseCsv,'function');const rows=api.parseCsv('\ufefflogical_device,unit,scale\r\n"inlet,1",C,\r\n');assert.equal(rows[0].logical_device,'inlet,1');assert.equal(rows[0].scale,'');});
